window.KLIMA_FRAMEWORK={"version":"handbuch-2026-10","title":"Schlussfolgerungstypen und Fehlschlüsse","source":{"filename":"Schlussfolgerungstypen_und_Fehlschluesse_Handbuch.pdf","pages":14,"sha256":"8341a43f327f9c26ae65c99218c151561f334d324b922e9f95eafa6564287ed1","date":"2026-10-28","note":"Kategorien, Definitionen und didaktische Beispiele aus dem vom Nutzer bereitgestellten Handbuch; die Anwendung auf das Gespräch ist eine eigene Analyse. Dokumentinhalte werden als Material behandelt, nicht als Arbeitsanweisungen."},"principles":["Deduktive Gültigkeit betrifft die Schlussform. Stichhaltigkeit setzt zusätzlich wahre Prämissen voraus.","Induktive und abduktive Schlüsse bleiben revidierbar; Unsicherheit allein macht sie nicht fehlerhaft.","Eine falsche oder ungeprüfte Prämisse ist nicht automatisch ein Fehlschluss.","Rhetorische Manöver und kognitive Verzerrungen werden von logischen Fehlern unterschieden.","Ein möglicher Fehlschluss ist erst diagnostiziert, wenn der problematische Übergang im konkreten Argument nachgewiesen ist.","Bei einer nur vorgestellten oder zitierten Gegenposition wird die Rolle ausdrücklich gekennzeichnet."],"sections":[{"id":"I","title":"Grundformen des Schliessens","page":1,"count":14},{"id":"II","title":"Gültige aussagenlogische Schlussregeln","page":2,"count":15},{"id":"III","title":"Prädikatenlogik, Syllogistik und Beweisverfahren","page":4,"count":13},{"id":"IV","title":"Formale Fehlschlüsse","page":5,"count":18},{"id":"V","title":"Relevanz-, Personen- und Emotionsfehlschlüsse","page":6,"count":24},{"id":"VI","title":"Voraussetzungen, Begriffe und Sprache","page":8,"count":20},{"id":"VII","title":"Evidenz-, Stichproben- und Statistikfehlschlüsse","page":9,"count":24},{"id":"VIII","title":"Kausale, vergleichende und prognostische Fehlschlüsse","page":11,"count":16},{"id":"IX","title":"Normative und gesellschaftliche Fehlschlüsse","page":12,"count":8},{"id":"X","title":"Argumentationsmanöver und kognitive Verzerrungen (Abgrenzung)","page":13,"count":12}],"entries":[{"id":"I-01","section":"I","name":"Deduktion","page":1,"definition":"Die Konklusion folgt bei gültiger Form notwendig aus den Prämissen; Wahrheit der Prämissen ist eine zusätzliche Frage.","example":"Alle Säugetiere sind Wirbeltiere; Wale sind Säugetiere; also sind Wale Wirbeltiere.","applications":[{"argument":"A002","scene":"s01"},{"argument":"A041","scene":"s15"},{"argument":"A049","scene":"s18"},{"argument":"A054","scene":"s20"},{"argument":"A089","scene":"s31"},{"argument":"A094","scene":"s33"},{"argument":"A113","scene":"s39"},{"argument":"A153","scene":"s51"}]},{"id":"I-02","section":"I","name":"Induktion (verallgemeinernd)","page":1,"definition":"Von beobachteten Fällen auf eine allgemeine Regel; die Folgerung bleibt revidierbar.","example":"Viele beobachtete Schwäne sind weiss; vermutlich sind Schwäne häufig weiss.","applications":[{"argument":"A015","scene":"s05"},{"argument":"A023","scene":"s08"},{"argument":"A026","scene":"s10"},{"argument":"A051","scene":"s19"},{"argument":"A058","scene":"s21"},{"argument":"A059","scene":"s22"},{"argument":"A073","scene":"s26"},{"argument":"A083","scene":"s29"},{"argument":"A107","scene":"s37"},{"argument":"A116","scene":"s40"},{"argument":"A121","scene":"s41"},{"argument":"A122","scene":"s42"},{"argument":"A123","scene":"s42"},{"argument":"A125","scene":"s43"},{"argument":"A136","scene":"s46"},{"argument":"A137","scene":"s46"},{"argument":"A143","scene":"s48"},{"argument":"A146","scene":"s49"},{"argument":"A151","scene":"s51"},{"argument":"A154","scene":"s52"},{"argument":"A156","scene":"s53"},{"argument":"A157","scene":"s53"},{"argument":"A161","scene":"s54"}]},{"id":"I-03","section":"I","name":"Abduktion (Schluss auf die beste Erklärung)","page":1,"definition":"Eine Hypothese wird gewählt, weil sie Beobachtungen vergleichsweise gut erklärt.","example":"Der Boden ist nass; Regen wäre eine plausible Erklärung, aber nicht die einzige.","applications":[{"argument":"A001","scene":"s01"},{"argument":"A003","scene":"s02"},{"argument":"A017","scene":"s06"},{"argument":"A025","scene":"s09"},{"argument":"A073","scene":"s26"},{"argument":"A074","scene":"s26"},{"argument":"A117","scene":"s40"},{"argument":"A138","scene":"s47"},{"argument":"A139","scene":"s47"},{"argument":"A140","scene":"s47"},{"argument":"A141","scene":"s47"},{"argument":"A147","scene":"s49"},{"argument":"A151","scene":"s51"},{"argument":"A155","scene":"s52"},{"argument":"A156","scene":"s53"},{"argument":"A161","scene":"s54"}]},{"id":"I-04","section":"I","name":"Analogieschluss","page":2,"definition":"Ähnlichkeiten in relevanten Merkmalen stützen eine weitere Ähnlichkeitsannahme.","example":"Zwei Schulmodelle ähneln sich in Struktur und Ressourcen; die erprobte Lernmethode könnte auch im zweiten funktionieren.","applications":[{"argument":"A010","scene":"s04"},{"argument":"A024","scene":"s09"},{"argument":"A027","scene":"s10"},{"argument":"A050","scene":"s18"},{"argument":"A065","scene":"s23"},{"argument":"A068","scene":"s24"},{"argument":"A070","scene":"s25"},{"argument":"A072","scene":"s25"},{"argument":"A079","scene":"s28"},{"argument":"A080","scene":"s28"},{"argument":"A081","scene":"s28"},{"argument":"A085","scene":"s30"},{"argument":"A088","scene":"s31"},{"argument":"A091","scene":"s32"},{"argument":"A093","scene":"s32"},{"argument":"A095","scene":"s33"},{"argument":"A109","scene":"s37"},{"argument":"A115","scene":"s39"},{"argument":"A123","scene":"s42"},{"argument":"A132","scene":"s45"},{"argument":"A136","scene":"s46"},{"argument":"A152","scene":"s51"}]},{"id":"I-05","section":"I","name":"Statistischer Schluss","page":2,"definition":"Von Häufigkeiten oder Wahrscheinlichkeiten auf Einzelfälle oder Populationen schliessen.","example":"80 % einer gut definierten Gruppe wählen A; für ein zufällig gezogenes Mitglied ist A wahrscheinlicher.","applications":[{"argument":"A023","scene":"s08"},{"argument":"A053","scene":"s20"},{"argument":"A083","scene":"s29"}]},{"id":"I-06","section":"I","name":"Kausaler Schluss","page":2,"definition":"Aus Evidenz wird auf eine Ursache-Wirkungs-Beziehung geschlossen; Alternativerklärungen sind zu prüfen.","example":"Nach einer randomisierten Intervention steigt die Leistung in der Versuchsgruppe; die Intervention kann ursächlich sein.","applications":[{"argument":"A003","scene":"s02"},{"argument":"A004","scene":"s02"},{"argument":"A008","scene":"s03"},{"argument":"A011","scene":"s04"},{"argument":"A012","scene":"s04"},{"argument":"A014","scene":"s05"},{"argument":"A016","scene":"s06"},{"argument":"A017","scene":"s06"},{"argument":"A019","scene":"s07"},{"argument":"A021","scene":"s07"},{"argument":"A024","scene":"s09"},{"argument":"A028","scene":"s10"},{"argument":"A031","scene":"s11"},{"argument":"A033","scene":"s12"},{"argument":"A047","scene":"s17"},{"argument":"A048","scene":"s17"},{"argument":"A055","scene":"s20"},{"argument":"A059","scene":"s22"},{"argument":"A060","scene":"s22"},{"argument":"A075","scene":"s26"},{"argument":"A076","scene":"s27"},{"argument":"A077","scene":"s27"},{"argument":"A081","scene":"s28"},{"argument":"A086","scene":"s30"},{"argument":"A087","scene":"s31"},{"argument":"A096","scene":"s33"},{"argument":"A099","scene":"s34"},{"argument":"A103","scene":"s35"},{"argument":"A104","scene":"s36"},{"argument":"A106","scene":"s37"},{"argument":"A107","scene":"s37"},{"argument":"A108","scene":"s37"},{"argument":"A109","scene":"s37"},{"argument":"A114","scene":"s39"},{"argument":"A117","scene":"s40"},{"argument":"A118","scene":"s41"},{"argument":"A119","scene":"s41"},{"argument":"A122","scene":"s42"},{"argument":"A127","scene":"s43"},{"argument":"A129","scene":"s44"},{"argument":"A138","scene":"s47"},{"argument":"A139","scene":"s47"},{"argument":"A140","scene":"s47"},{"argument":"A143","scene":"s48"},{"argument":"A147","scene":"s49"},{"argument":"A155","scene":"s52"}]},{"id":"I-07","section":"I","name":"Prädiktiver Schluss","page":2,"definition":"Aus Daten, Regeln und Annahmen wird eine Prognose für künftige Ereignisse formuliert.","example":"Bei gleichbleibender Nachfrage dürften die Preise steigen.","applications":[{"argument":"A012","scene":"s04"},{"argument":"A014","scene":"s05"},{"argument":"A015","scene":"s05"},{"argument":"A016","scene":"s06"},{"argument":"A021","scene":"s07"},{"argument":"A023","scene":"s08"},{"argument":"A027","scene":"s10"},{"argument":"A028","scene":"s10"},{"argument":"A031","scene":"s11"},{"argument":"A044","scene":"s16"},{"argument":"A050","scene":"s18"},{"argument":"A056","scene":"s21"},{"argument":"A058","scene":"s21"},{"argument":"A061","scene":"s22"},{"argument":"A062","scene":"s22"},{"argument":"A076","scene":"s27"},{"argument":"A077","scene":"s27"},{"argument":"A081","scene":"s28"},{"argument":"A082","scene":"s29"},{"argument":"A096","scene":"s33"},{"argument":"A097","scene":"s33"},{"argument":"A098","scene":"s34"},{"argument":"A104","scene":"s36"},{"argument":"A106","scene":"s37"},{"argument":"A130","scene":"s44"},{"argument":"A137","scene":"s46"},{"argument":"A160","scene":"s54"},{"argument":"A162","scene":"s55"},{"argument":"A163","scene":"s55"}]},{"id":"I-08","section":"I","name":"Praktischer Schluss","page":2,"definition":"Aus Zielen, Mitteln und Nebenbedingungen wird eine Handlung abgeleitet; normative Prämissen sind nötig.","example":"Um Energie zu sparen, sollen wir bei unverändertem Komfort eine effizientere Heizung wählen.","applications":[{"argument":"A005","scene":"s02"},{"argument":"A006","scene":"s03"},{"argument":"A007","scene":"s03"},{"argument":"A008","scene":"s03"},{"argument":"A018","scene":"s07"},{"argument":"A020","scene":"s07"},{"argument":"A029","scene":"s11"},{"argument":"A033","scene":"s12"},{"argument":"A034","scene":"s13"},{"argument":"A036","scene":"s14"},{"argument":"A038","scene":"s14"},{"argument":"A042","scene":"s15"},{"argument":"A043","scene":"s16"},{"argument":"A044","scene":"s16"},{"argument":"A045","scene":"s16"},{"argument":"A048","scene":"s17"},{"argument":"A052","scene":"s19"},{"argument":"A053","scene":"s20"},{"argument":"A056","scene":"s21"},{"argument":"A057","scene":"s21"},{"argument":"A058","scene":"s21"},{"argument":"A061","scene":"s22"},{"argument":"A062","scene":"s22"},{"argument":"A063","scene":"s23"},{"argument":"A064","scene":"s23"},{"argument":"A065","scene":"s23"},{"argument":"A067","scene":"s24"},{"argument":"A068","scene":"s24"},{"argument":"A069","scene":"s24"},{"argument":"A070","scene":"s25"},{"argument":"A071","scene":"s25"},{"argument":"A074","scene":"s26"},{"argument":"A075","scene":"s26"},{"argument":"A084","scene":"s29"},{"argument":"A087","scene":"s31"},{"argument":"A088","scene":"s31"},{"argument":"A089","scene":"s31"},{"argument":"A091","scene":"s32"},{"argument":"A092","scene":"s32"},{"argument":"A094","scene":"s33"},{"argument":"A095","scene":"s33"},{"argument":"A098","scene":"s34"},{"argument":"A099","scene":"s34"},{"argument":"A100","scene":"s34"},{"argument":"A101","scene":"s35"},{"argument":"A103","scene":"s35"},{"argument":"A105","scene":"s36"},{"argument":"A106","scene":"s37"},{"argument":"A108","scene":"s37"},{"argument":"A110","scene":"s38"},{"argument":"A112","scene":"s39"},{"argument":"A113","scene":"s39"},{"argument":"A114","scene":"s39"},{"argument":"A115","scene":"s39"},{"argument":"A119","scene":"s41"},{"argument":"A120","scene":"s41"},{"argument":"A121","scene":"s41"},{"argument":"A124","scene":"s42"},{"argument":"A127","scene":"s43"},{"argument":"A128","scene":"s43"},{"argument":"A129","scene":"s44"},{"argument":"A130","scene":"s44"},{"argument":"A132","scene":"s45"},{"argument":"A133","scene":"s45"},{"argument":"A134","scene":"s45"},{"argument":"A137","scene":"s46"},{"argument":"A142","scene":"s48"},{"argument":"A144","scene":"s48"},{"argument":"A145","scene":"s49"},{"argument":"A148","scene":"s50"},{"argument":"A149","scene":"s50"},{"argument":"A153","scene":"s51"},{"argument":"A158","scene":"s53"},{"argument":"A160","scene":"s54"},{"argument":"A162","scene":"s55"},{"argument":"A163","scene":"s55"}]},{"id":"I-09","section":"I","name":"Defeasibles (aufhebbares) Schliessen","page":2,"definition":"Ein Schluss gilt vorbehaltlich neuer Gegeninformation.","example":"Vögel fliegen typischerweise; dieses Tier ist ein Vogel; vorläufig nehme ich an, dass es fliegen kann.","applications":[{"argument":"A004","scene":"s02"},{"argument":"A025","scene":"s09"},{"argument":"A032","scene":"s11"},{"argument":"A047","scene":"s17"},{"argument":"A051","scene":"s19"},{"argument":"A055","scene":"s20"},{"argument":"A082","scene":"s29"},{"argument":"A090","scene":"s31"},{"argument":"A101","scene":"s35"},{"argument":"A112","scene":"s39"},{"argument":"A122","scene":"s42"}]},{"id":"I-10","section":"I","name":"Probabilistisches/bayesisches Schliessen","page":2,"definition":"Evidenz verändert die Wahrscheinlichkeit einer Hypothese; Vorwahrscheinlichkeit und Testgüte sind entscheidend.","example":"Ein positiver Test erhöht die Krankheitswahrscheinlichkeit; wie stark, hängt von Prävalenz und Testqualität ab.","applications":[]},{"id":"I-11","section":"I","name":"Kontrafaktisches Schliessen","page":2,"definition":"Gedanklich wird geprüft, was unter veränderten Bedingungen eingetreten wäre.","example":"Ohne die Sperrung wäre der Zug vermutlich pünktlich angekommen.","applications":[{"argument":"A018","scene":"s07"},{"argument":"A019","scene":"s07"},{"argument":"A052","scene":"s19"},{"argument":"A060","scene":"s22"},{"argument":"A092","scene":"s32"},{"argument":"A149","scene":"s50"}]},{"id":"I-12","section":"I","name":"Indirekter Beweis / Reductio ad absurdum","page":2,"definition":"Man nimmt das Gegenteil der Behauptung an und zeigt einen Widerspruch.","example":"Wäre die Quadratwurzel aus 2 rational, ergäbe sich ein Widerspruch; also ist sie irrational.","applications":[{"argument":"A066","scene":"s23"}]},{"id":"I-13","section":"I","name":"Transduktiver Schluss","page":2,"definition":"Einzelfall-zu-Einzelfall-Übertragung, besonders in Entwicklungspsychologie und Analogien; keine deduktive Garantie.","example":"Das neue Experiment ähnelt einem früheren; womöglich ergibt sich ein ähnliches Resultat.","applications":[{"argument":"A079","scene":"s28"},{"argument":"A080","scene":"s28"}]},{"id":"I-14","section":"I","name":"Dialektischer Schluss","page":2,"definition":"Eine Position wird unter Einbezug von Einwänden und Gegenargumenten differenziert weiterentwickelt; keine einzelne formale Schlussregel.","example":"Ein Vorschlag überzeugt teilweise, ein Einwand erzwingt jedoch eine engere Bedingung.","applications":[{"argument":"A002","scene":"s01"},{"argument":"A006","scene":"s03"},{"argument":"A009","scene":"s04"},{"argument":"A011","scene":"s04"},{"argument":"A013","scene":"s05"},{"argument":"A020","scene":"s07"},{"argument":"A022","scene":"s08"},{"argument":"A030","scene":"s11"},{"argument":"A032","scene":"s11"},{"argument":"A034","scene":"s13"},{"argument":"A035","scene":"s13"},{"argument":"A037","scene":"s14"},{"argument":"A038","scene":"s14"},{"argument":"A039","scene":"s15"},{"argument":"A040","scene":"s15"},{"argument":"A041","scene":"s15"},{"argument":"A045","scene":"s16"},{"argument":"A046","scene":"s17"},{"argument":"A049","scene":"s18"},{"argument":"A054","scene":"s20"},{"argument":"A057","scene":"s21"},{"argument":"A063","scene":"s23"},{"argument":"A066","scene":"s23"},{"argument":"A072","scene":"s25"},{"argument":"A078","scene":"s27"},{"argument":"A083","scene":"s29"},{"argument":"A085","scene":"s30"},{"argument":"A086","scene":"s30"},{"argument":"A090","scene":"s31"},{"argument":"A097","scene":"s33"},{"argument":"A102","scene":"s35"},{"argument":"A110","scene":"s38"},{"argument":"A111","scene":"s38"},{"argument":"A116","scene":"s40"},{"argument":"A118","scene":"s41"},{"argument":"A120","scene":"s41"},{"argument":"A125","scene":"s43"},{"argument":"A126","scene":"s43"},{"argument":"A128","scene":"s43"},{"argument":"A131","scene":"s44"},{"argument":"A133","scene":"s45"},{"argument":"A134","scene":"s45"},{"argument":"A135","scene":"s45"},{"argument":"A144","scene":"s48"},{"argument":"A145","scene":"s49"},{"argument":"A146","scene":"s49"},{"argument":"A149","scene":"s50"},{"argument":"A150","scene":"s50"},{"argument":"A152","scene":"s51"},{"argument":"A157","scene":"s53"},{"argument":"A159","scene":"s54"}]},{"id":"II-01","section":"II","name":"Modus ponens","page":2,"definition":"Aus «Wenn P, dann Q» und P folgt Q.","example":"Wenn der Alarm aktiv ist, leuchtet die Lampe. Der Alarm ist aktiv. Also leuchtet sie.","applications":[{"argument":"A089","scene":"s31"},{"argument":"A094","scene":"s33"},{"argument":"A113","scene":"s39"}]},{"id":"II-02","section":"II","name":"Modus tollens","page":3,"definition":"Aus «Wenn P, dann Q» und «nicht Q» folgt «nicht P».","example":"Wenn der Alarm aktiv ist, leuchtet die Lampe. Die Lampe leuchtet nicht. Also ist der Alarm nicht aktiv.","applications":[{"argument":"A002","scene":"s01"}]},{"id":"II-03","section":"II","name":"Hypothetischer Syllogismus","page":3,"definition":"Aus P → Q und Q → R folgt P → R.","example":"Wenn ich lerne, verstehe ich den Stoff; wenn ich ihn verstehe, löse ich die Aufgabe; also …","applications":[]},{"id":"II-04","section":"II","name":"Disjunktiver Syllogismus","page":3,"definition":"Aus P oder Q und nicht P folgt Q (inklusives Oder).","example":"Die Datei ist lokal oder in der Cloud; sie ist nicht lokal; also ist sie in der Cloud.","applications":[]},{"id":"II-05","section":"II","name":"Konjunktionseinführung","page":3,"definition":"Aus P und Q folgt P und Q.","example":"Es regnet. Es ist kalt. Also regnet es und ist kalt.","applications":[]},{"id":"II-06","section":"II","name":"Konjunktionselimination","page":3,"definition":"Aus P und Q folgt P (ebenso Q).","example":"Sie liest und schreibt; also liest sie.","applications":[]},{"id":"II-07","section":"II","name":"Disjunktionseinführung","page":3,"definition":"Aus P folgt P oder Q.","example":"Der Test ist bestanden; also ist der Test bestanden oder es regnet.","applications":[]},{"id":"II-08","section":"II","name":"Doppelnegationselimination (klassisch)","page":3,"definition":"Aus nicht nicht P folgt P; die Gültigkeit hängt vom Logiksystem ab.","example":"Es ist nicht der Fall, dass es nicht regnet; also regnet es.","applications":[]},{"id":"II-09","section":"II","name":"Bikonditionalelimination","page":3,"definition":"Aus P genau dann, wenn Q, folgt P → Q und Q → P.","example":"Ein Dreieck ist genau dann gleichseitig, wenn alle Seiten gleich lang sind.","applications":[]},{"id":"II-10","section":"II","name":"Bikonditionaleinführung","page":3,"definition":"Aus P → Q und Q → P folgt P ↔ Q.","example":"Beide Richtungen sind bewiesen; also gilt die Äquivalenz.","applications":[]},{"id":"II-11","section":"II","name":"Fallunterscheidung","page":3,"definition":"Aus P oder Q, P → R und Q → R folgt R.","example":"Egal ob Zug oder Bus: In beiden Fällen komme ich vor 9 Uhr an.","applications":[]},{"id":"II-12","section":"II","name":"Konstruktives Dilemma","page":3,"definition":"Aus P → R, Q → S und P oder Q folgt R oder S.","example":"Entweder ich fahre Rad und trainiere, oder ich gehe zu Fuss und bewege mich.","applications":[]},{"id":"II-13","section":"II","name":"Destruktives Dilemma","page":3,"definition":"Aus P → R, Q → S und nicht R oder nicht S folgt nicht P oder nicht Q.","example":"Wenn A, dann C; wenn B, dann D; nicht C oder nicht D; folglich nicht A oder nicht B.","applications":[]},{"id":"II-14","section":"II","name":"Resolution","page":3,"definition":"Aus P oder Q sowie nicht P oder R folgt Q oder R.","example":"«A oder B» und «nicht A oder C» erlauben «B oder C».","applications":[]},{"id":"II-15","section":"II","name":"Widerspruchsregel","page":3,"definition":"Aus P und nicht P folgt in klassischer Logik jede Aussage (Explosion); Widersprüche sind darum zu vermeiden.","example":"Ein inkonsistentes Axiomensystem erlaubt in klassischer Logik beliebige Folgerungen.","applications":[]},{"id":"III-01","section":"III","name":"Universelle Instanziierung","page":4,"definition":"Aus «Alle x sind F» folgt «a ist F» für ein Individuum der Domäne.","example":"Alle Metalle leiten Strom; Kupfer ist Metall; also leitet Kupfer Strom.","applications":[]},{"id":"III-02","section":"III","name":"Existenzielle Generalisierung","page":4,"definition":"Aus «a hat Eigenschaft F» folgt «Es gibt mindestens ein F».","example":"Dieser Apfel ist rot; folglich gibt es einen roten Apfel.","applications":[{"argument":"A049","scene":"s18"}]},{"id":"III-03","section":"III","name":"Universelle Generalisierung","page":4,"definition":"Von einem beliebigen, nicht speziell vorausgesetzten Individuum auf alle schliessen; Nebenbedingungen beachten.","example":"Für ein beliebiges n wurde die Eigenschaft gezeigt; folglich gilt sie für alle n.","applications":[]},{"id":"III-04","section":"III","name":"Existenzielle Instanziierung","page":4,"definition":"Aus «Es gibt ein F» wird mit einem frischen Platzhalternamen ein Zeuge angenommen, nicht eine beliebige bestimmte Person.","example":"Irgendwer besitzt den Schlüssel; bezeichne diese Person vorübergehend als k.","applications":[]},{"id":"III-05","section":"III","name":"Kategorischer Syllogismus (Barbara)","page":4,"definition":"Alle M sind P; alle S sind M; also alle S sind P.","example":"Alle Hunde sind Säugetiere; alle Pudel sind Hunde; alle Pudel sind Säugetiere.","applications":[]},{"id":"III-06","section":"III","name":"Kategorischer Syllogismus (Celarent)","page":4,"definition":"Kein M ist P; alle S sind M; also kein S ist P.","example":"Keine Primzahl grösser als 2 ist gerade; alle Zahlen der betrachteten Klasse sind Primzahlen grösser als 2; also ist keine gerade.","applications":[]},{"id":"III-07","section":"III","name":"Kategorischer Syllogismus (Darii)","page":4,"definition":"Alle M sind P; einige S sind M; also einige S sind P.","example":"Alle Rosen sind Pflanzen; einige Geschenke sind Rosen; einige Geschenke sind Pflanzen.","applications":[]},{"id":"III-08","section":"III","name":"Kategorischer Syllogismus (Ferio)","page":4,"definition":"Kein M ist P; einige S sind M; also einige S sind nicht P.","example":"Kein Quadrat ist ein Kreis; einige Figuren sind Quadrate; einige Figuren sind keine Kreise.","applications":[]},{"id":"III-09","section":"III","name":"Mathematische Induktion","page":4,"definition":"Beweis für alle natürlichen Zahlen: Basisfall und Schluss von n auf n+1; trotz Name deduktiv.","example":"Beweise Formel für n=1 und danach: Gilt sie für n, gilt sie auch für n+1.","applications":[]},{"id":"III-10","section":"III","name":"Beweis durch Kontraposition","page":4,"definition":"Statt P → Q wird die äquivalente Aussage nicht Q → nicht P bewiesen.","example":"Ist n² gerade, dann ist n gerade; zeige: Ist n ungerade, ist n² ungerade.","applications":[]},{"id":"III-11","section":"III","name":"Beweis durch Widerspruch","page":4,"definition":"Annahme des Gegenteils führt zum Widerspruch; klassischer Beweisweg.","example":"Angenommen, es gibt eine grösste Primzahl; daraus konstruiert man eine grössere.","applications":[{"argument":"A066","scene":"s23"}]},{"id":"III-12","section":"III","name":"Konstruktiver Existenzbeweis","page":4,"definition":"Man zeigt eine konkrete Instanz mit der geforderten Eigenschaft.","example":"Es gibt eine gerade Primzahl: 2.","applications":[]},{"id":"III-13","section":"III","name":"Nichtkonstruktiver Existenzbeweis","page":5,"definition":"Existenz wird ohne explizite Angabe eines Beispiels bewiesen.","example":"Ein Existenzsatz wird durch Widerspruch begründet, ohne den Zeugen zu berechnen.","applications":[]},{"id":"IV-01","section":"IV","name":"Bejahung des Konsequens (affirming the consequent)","page":5,"definition":"Aus P → Q und Q wird fälschlich P geschlossen.","example":"Wenn es regnet, ist die Strasse nass. Sie ist nass. Also regnet es. Fehler: andere Ursachen möglich.","applications":[{"argument":"A025","scene":"s09"}]},{"id":"IV-02","section":"IV","name":"Verneinung des Antezedens (denying the antecedent)","page":5,"definition":"Aus P → Q und nicht P wird fälschlich nicht Q geschlossen.","example":"Wenn ich in Zürich wohne, wohne ich in der Schweiz. Ich wohne nicht in Zürich; also nicht in der Schweiz.","applications":[]},{"id":"IV-03","section":"IV","name":"Fehler der inversen Beziehung","page":5,"definition":"Aus P → Q wird fälschlich Q → P abgeleitet.","example":"Jeder Pudel ist ein Hund; also sei jeder Hund ein Pudel.","applications":[]},{"id":"IV-04","section":"IV","name":"Unzulässige Konversion","page":5,"definition":"Subjekt und Prädikat einer Allaussage werden unerlaubt vertauscht.","example":"Alle Katzen sind Tiere; folglich sind alle Tiere Katzen.","applications":[]},{"id":"IV-05","section":"IV","name":"Unverteilter Mittelbegriff","page":5,"definition":"Zwei Klassen teilen ein Merkmal; daraus folgt nicht, dass sie sich überlappen.","example":"Alle Katzen sind Säugetiere; alle Hunde sind Säugetiere; also sind Hunde Katzen.","applications":[]},{"id":"IV-06","section":"IV","name":"Vier-Termini-Fehler","page":5,"definition":"Ein scheinbarer Syllogismus gebraucht in Wahrheit vier Begriffe, oft wegen Doppeldeutigkeit.","example":"Jede Bank ist ein Finanzinstitut; am Fluss steht eine Bank; also steht ein Finanzinstitut am Fluss.","applications":[]},{"id":"IV-07","section":"IV","name":"Illegitimer Oberbegriff","page":5,"definition":"Ein Begriff wird in der Konklusion allgemeiner verwendet als in der Prämisse.","example":"Alle Hunde sind Tiere; keine Katzen sind Hunde; also sind keine Katzen Tiere.","applications":[]},{"id":"IV-08","section":"IV","name":"Illegitimer Unterbegriff","page":5,"definition":"Der Unterbegriff wird in der Konklusion unzulässig erweitert.","example":"Alle Hunde sind Säugetiere; alle Hunde sind Haustiere; also sind alle Haustiere Säugetiere.","applications":[]},{"id":"IV-09","section":"IV","name":"Zwei negative Prämissen","page":5,"definition":"Aus zwei verneinenden kategorischen Prämissen folgt ohne weitere Information keine kategoriale Konklusion.","example":"Kein Hund ist ein Vogel; kein Fisch ist ein Hund; also kein Fisch ist ein Vogel.","applications":[]},{"id":"IV-10","section":"IV","name":"Bejahende Konklusion aus negativer Prämisse","page":5,"definition":"Bei Standard-Syllogismen kann eine negative Prämisse keine bejahende Konklusion tragen.","example":"Keine Katzen sind Hunde; alle Pudel sind Hunde; also seien alle Pudel Katzen.","applications":[]},{"id":"IV-11","section":"IV","name":"Existenzfehlschluss","page":5,"definition":"Aus einer universellen Aussage wird ohne Existenzprämisse auf vorhandene Instanzen geschlossen.","example":"Alle Einhörner haben Hörner; also gibt es Einhörner.","applications":[]},{"id":"IV-12","section":"IV","name":"Unzulässige Quantorenumkehr","page":5,"definition":"«Für alle x gibt es ein y» wird zu «Es gibt ein y für alle x».","example":"Jede Person hat eine Mutter; also hätten alle dieselbe Mutter.","applications":[]},{"id":"IV-13","section":"IV","name":"Affirmation einer Disjunktion","page":6,"definition":"Aus P oder Q und P wird bei inklusivem Oder fälschlich nicht Q geschlossen.","example":"Anna spricht Französisch oder Englisch. Sie spricht Französisch; also kein Englisch.","applications":[]},{"id":"IV-14","section":"IV","name":"Fehlschluss durch falsche Negation","page":6,"definition":"Die Negation eines zusammengesetzten Satzes wird falsch gebildet (De Morgan).","example":"Nicht (P und Q) heisst nicht «nicht P und nicht Q», sondern «nicht P oder nicht Q».","applications":[]},{"id":"IV-15","section":"IV","name":"Modaler Fehlschluss","page":6,"definition":"Möglichkeit und Notwendigkeit werden verwechselt.","example":"Möglicherweise gewinnt A; folglich muss A gewinnen.","applications":[{"argument":"A097","scene":"s33"}]},{"id":"IV-16","section":"IV","name":"Verwechslung notwendiger und hinreichender Bedingung","page":6,"definition":"Aus «P ist notwendig für Q» wird P als hinreichend für Q verstanden.","example":"Sauerstoff ist fürs Feuer notwendig; Sauerstoff allein bewirkt aber kein Feuer.","applications":[{"argument":"A008","scene":"s03"},{"argument":"A042","scene":"s15"},{"argument":"A098","scene":"s34"},{"argument":"A099","scene":"s34"},{"argument":"A102","scene":"s35"},{"argument":"A105","scene":"s36"},{"argument":"A108","scene":"s37"},{"argument":"A114","scene":"s39"},{"argument":"A127","scene":"s43"},{"argument":"A153","scene":"s51"}]},{"id":"IV-17","section":"IV","name":"Ungültiger Wahrscheinlichkeitsschluss","page":6,"definition":"Wahrscheinlichkeiten werden ohne zulässige Operation addiert, multipliziert oder umgekehrt.","example":"Zwei je 70 % wahrscheinliche Ereignisse sind nicht automatisch gemeinsam zu 49 % wahrscheinlich, wenn sie abhängig sind.","applications":[]},{"id":"IV-18","section":"IV","name":"Non sequitur (formal)","page":6,"definition":"Die Konklusion folgt logisch nicht aus den angeführten Prämissen; Oberbegriff für formale Ungültigkeit.","example":"Die Bibliothek ist offen; also ist der Unterricht gut.","applications":[]},{"id":"V-01","section":"V","name":"Ad hominem (persönlicher Angriff)","page":6,"definition":"Die Person wird angegriffen, statt ihr Argument zu prüfen.","example":"«Dein Steuerargument ist falsch, denn du bist unsympathisch.»","applications":[]},{"id":"V-02","section":"V","name":"Tu quoque («Du auch»)","page":6,"definition":"Ein Vorwurf der Inkonsistenz soll die Sachfrage erledigen.","example":"«Du fährst Auto; also ist deine Kritik am Verkehr falsch.»","applications":[{"argument":"A118","scene":"s41"},{"argument":"A120","scene":"s41"},{"argument":"A149","scene":"s50"}]},{"id":"V-03","section":"V","name":"Circumstantial ad hominem","page":6,"definition":"Interessen oder Umstände einer Person ersetzen die Prüfung ihrer Begründung.","example":"«Sie ist Lehrerin, deshalb kann ihre Bildungsstudie nicht stimmen.»","applications":[{"argument":"A039","scene":"s15"}]},{"id":"V-04","section":"V","name":"Vergiftung des Brunnens","page":6,"definition":"Vorab wird eine Quelle diskreditiert, damit spätere Aussagen nicht mehr zählen.","example":"«Alles, was er jetzt sagt, ist ohnehin Propaganda.»","applications":[]},{"id":"V-05","section":"V","name":"Genetischer Fehlschluss","page":6,"definition":"Der Ursprung einer Idee gilt automatisch als Beweis für ihre Wahrheit oder Falschheit.","example":"«Die Idee stammt von einer Firma, daher ist sie falsch.»","applications":[]},{"id":"V-06","section":"V","name":"Schuld durch Assoziation","page":6,"definition":"Eine Behauptung wird durch entfernte Verbindung zu missbilligten Personen abgewertet.","example":"«Auch ein Extremist fordert das; also ist die Forderung falsch.»","applications":[{"argument":"A045","scene":"s16"}]},{"id":"V-07","section":"V","name":"Appell an Autorität (ad verecundiam)","page":6,"definition":"Ein Autoritätsverweis ersetzt Fachkompetenz, Evidenz oder Prüfung.","example":"«Der Schauspieler sagt, die Therapie helfe; also wirkt sie.»","applications":[{"argument":"A029","scene":"s11"},{"argument":"A038","scene":"s14"},{"argument":"A041","scene":"s15"},{"argument":"A067","scene":"s24"},{"argument":"A098","scene":"s34"},{"argument":"A122","scene":"s42"},{"argument":"A143","scene":"s48"},{"argument":"A145","scene":"s49"}]},{"id":"V-08","section":"V","name":"Appell an Popularität (ad populum)","page":7,"definition":"Mehrheitszustimmung wird als Wahrheitsbeweis verwendet.","example":"«Millionen teilen den Beitrag; er muss stimmen.»","applications":[]},{"id":"V-09","section":"V","name":"Appell an Tradition","page":7,"definition":"Lange Übung wird zur alleinigen Rechtfertigung.","example":"«Das machen wir seit 50 Jahren; darum ist es richtig.»","applications":[{"argument":"A159","scene":"s54"}]},{"id":"V-10","section":"V","name":"Appell an Neuheit","page":7,"definition":"Etwas gilt allein wegen seiner Neuheit als besser.","example":"«Die neue Software ist neuer; daher sicher besser.»","applications":[{"argument":"A084","scene":"s29"},{"argument":"A160","scene":"s54"},{"argument":"A163","scene":"s55"}]},{"id":"V-11","section":"V","name":"Appell an Unwissenheit (ad ignorantiam)","page":7,"definition":"Fehlende Widerlegung wird als Beweis behandelt oder umgekehrt.","example":"«Niemand hat bewiesen, dass es das nicht gibt; also existiert es.»","applications":[{"argument":"A032","scene":"s11"}]},{"id":"V-12","section":"V","name":"Appell an Mitleid (ad misericordiam)","page":7,"definition":"Mitleid ersetzt die sachlich relevante Begründung.","example":"«Gib mir eine Bestnote, denn ich hatte eine anstrengende Woche.»","applications":[{"argument":"A070","scene":"s25"}]},{"id":"V-13","section":"V","name":"Appell an Angst","page":7,"definition":"Angst soll eine Behauptung belegen, ohne die Evidenz zu liefern.","example":"«Wenn du nicht zustimmst, wird alles zusammenbrechen.»","applications":[]},{"id":"V-14","section":"V","name":"Appell an Drohung (ad baculum)","page":7,"definition":"Druck oder Sanktionen ersetzen eine argumentative Begründung.","example":"«Meine These stimmt; andernfalls verlierst du deine Stelle.»","applications":[]},{"id":"V-15","section":"V","name":"Appell an Schmeichelei / Eitelkeit","page":7,"definition":"Zustimmung wird durch Komplimente statt Gründe herbeigeführt.","example":"«Intelligente Menschen unterstützen selbstverständlich meinen Antrag.»","applications":[]},{"id":"V-16","section":"V","name":"Appell an Reichtum / Armut","page":7,"definition":"Finanzieller Status wird als Wahrheitsmassstab genutzt.","example":"«Er ist reich; seine Wirtschaftsprognose muss stimmen.»","applications":[]},{"id":"V-17","section":"V","name":"Appell an Natur (appeal to nature)","page":7,"definition":"Natürliches gilt pauschal als gut, Künstliches als schlecht.","example":"«Es ist pflanzlich, also kann es nicht schaden.»","applications":[{"argument":"A157","scene":"s53"}]},{"id":"V-18","section":"V","name":"Appell an Konsequenzen (ad consequentiam)","page":7,"definition":"Erwünschte oder unerwünschte Folgen des Glaubens an eine These entscheiden über ihre Wahrheit.","example":"«Diese Diagnose wäre unangenehm; darum kann sie nicht stimmen.»","applications":[{"argument":"A020","scene":"s07"},{"argument":"A075","scene":"s26"}]},{"id":"V-19","section":"V","name":"Lächerlichmachen (appeal to ridicule)","page":7,"definition":"Eine Position wird verspottet statt widerlegt.","example":"«Was für eine lächerliche Idee; damit ist sie erledigt.»","applications":[{"argument":"A079","scene":"s28"}]},{"id":"V-20","section":"V","name":"Roter Hering (red herring)","page":7,"definition":"Ein irrelevantes Thema lenkt von der Streitfrage ab.","example":"Auf die Frage nach Kosten wird ausführlich über das Schulmaskottchen gesprochen.","applications":[]},{"id":"V-21","section":"V","name":"Whataboutism","page":7,"definition":"Eine Kritik wird mit einem fremden Fehlverhalten abgewehrt.","example":"«Warum über unsere Emissionen sprechen? Das andere Land verschmutzt auch.»","applications":[{"argument":"A110","scene":"s38"},{"argument":"A118","scene":"s41"}]},{"id":"V-22","section":"V","name":"Ignoratio elenchi (Thema verfehlt)","page":8,"definition":"Ein Argument belegt eine andere als die strittige These.","example":"Gefragt ist, ob ein Projekt finanzierbar ist; geantwortet wird, es sei spannend.","applications":[{"argument":"A057","scene":"s21"},{"argument":"A111","scene":"s38"},{"argument":"A113","scene":"s39"}]},{"id":"V-23","section":"V","name":"Strohmann","page":8,"definition":"Die Gegenposition wird verzerrt und die Verzerrung angegriffen.","example":"«Du willst weniger Prüfungen? Also willst du keine Leistung mehr.»","applications":[{"argument":"A006","scene":"s03"},{"argument":"A078","scene":"s27"}]},{"id":"V-24","section":"V","name":"Motte-and-Bailey","page":8,"definition":"Zwischen einer weitgehenden und einer unstrittigeren These wird je nach Kritik gewechselt.","example":"Erst «Alle Medien lügen», bei Nachfrage nur «Medien machen manchmal Fehler».","applications":[]},{"id":"VI-01","section":"VI","name":"Zirkelschluss / Petitio principii","page":8,"definition":"Die zu beweisende Behauptung wird als Prämisse vorausgesetzt.","example":"«Das Gesetz ist gerecht, weil es ein gerechtes Gesetz ist.»","applications":[]},{"id":"VI-02","section":"VI","name":"Geladene Frage (complex question)","page":8,"definition":"Eine Frage unterstellt eine unbewiesene Voraussetzung.","example":"«Wann hast du aufgehört, bei Prüfungen zu schummeln?»","applications":[{"argument":"A001","scene":"s01"},{"argument":"A150","scene":"s50"}]},{"id":"VI-03","section":"VI","name":"Falsches Dilemma","page":8,"definition":"Mehr als zwei realistische Alternativen werden auf zwei reduziert.","example":"«Entweder Präsenzunterricht oder gar kein Lernen.»","applications":[{"argument":"A009","scene":"s04"},{"argument":"A045","scene":"s16"},{"argument":"A103","scene":"s35"},{"argument":"A131","scene":"s44"}]},{"id":"VI-04","section":"VI","name":"Kontinuumsfehlschluss / Sorites-Missbrauch","page":8,"definition":"Unscharfe Grenzen sollen zeigen, dass es überhaupt keine Unterschiede gibt.","example":"«Es gibt keine exakte Grenze zum Reichtum; also ist niemand reich.»","applications":[]},{"id":"VI-05","section":"VI","name":"Äquivokation","page":8,"definition":"Dasselbe Wort wird in unterschiedlichen Bedeutungen gebraucht.","example":"«Eine Feder ist leicht; was leicht ist, ist einfach; also ist eine Feder einfach.»","applications":[{"argument":"A022","scene":"s08"},{"argument":"A034","scene":"s13"},{"argument":"A035","scene":"s13"},{"argument":"A046","scene":"s17"},{"argument":"A054","scene":"s20"},{"argument":"A083","scene":"s29"},{"argument":"A085","scene":"s30"},{"argument":"A086","scene":"s30"},{"argument":"A128","scene":"s43"}]},{"id":"VI-06","section":"VI","name":"Amphibolie","page":8,"definition":"Eine grammatisch mehrdeutige Formulierung erzeugt einen Scheinbeweis.","example":"«Ich sah den Mann mit dem Fernglas»: Wer hatte das Fernglas?","applications":[]},{"id":"VI-07","section":"VI","name":"Betonungsfehlschluss","page":8,"definition":"Veränderte Hervorhebung verändert Sinn oder Schluss.","example":"«Sie hat NICHT gesagt, er habe gestohlen» wird ohne Betonung uminterpretiert.","applications":[]},{"id":"VI-08","section":"VI","name":"Kompositionsfehlschluss","page":8,"definition":"Was für Teile gilt, wird ohne Begründung dem Ganzen zugeschrieben.","example":"«Jeder Spieler ist hervorragend; das Team muss hervorragend sein.»","applications":[{"argument":"A018","scene":"s07"},{"argument":"A051","scene":"s19"},{"argument":"A066","scene":"s23"}]},{"id":"VI-09","section":"VI","name":"Divisionsfehlschluss","page":8,"definition":"Was für das Ganze gilt, wird jedem Teil zugeschrieben.","example":"«Die Schule ist reich; also besitzt jede Schülerin viel Geld.»","applications":[{"argument":"A058","scene":"s21"},{"argument":"A072","scene":"s25"},{"argument":"A112","scene":"s39"},{"argument":"A116","scene":"s40"},{"argument":"A135","scene":"s45"},{"argument":"A148","scene":"s50"}]},{"id":"VI-10","section":"VI","name":"Kategorienfehler","page":8,"definition":"Begriffe werden auf Gegenstände der falschen logischen Kategorie angewandt.","example":"«Wo befindet sich neben den Gebäuden die Universität selbst?»","applications":[]},{"id":"VI-11","section":"VI","name":"Reifikation (Verdinglichung)","page":9,"definition":"Ein abstrakter Begriff wird wie ein selbstständig handelndes Ding behandelt.","example":"«Der Markt will Rache» ohne Erklärung von Akteuren und Mechanismen.","applications":[{"argument":"A055","scene":"s20"},{"argument":"A134","scene":"s45"}]},{"id":"VI-12","section":"VI","name":"Persuasive Definition","page":9,"definition":"Ein Begriff wird wertend so umdefiniert, dass die Schlussfolgerung vorweggenommen ist.","example":"«Wahre Bildung ist ausschliesslich das, was unser Konzept bietet.»","applications":[{"argument":"A040","scene":"s15"}]},{"id":"VI-13","section":"VI","name":"Kein wahrer Schotte","page":9,"definition":"Gegenbeispiele werden durch spontane Umdefinition ausgeschlossen.","example":"«Ein echter Fan kritisiert den Verein nie.»","applications":[]},{"id":"VI-14","section":"VI","name":"Moving the goalposts (Torpfosten verschieben)","page":9,"definition":"Nach Erfüllung der Beweisforderung werden neue Kriterien eingeführt.","example":"«Zeig eine Studie» – Studie gezeigt – «Nur zehn Studien zählen.»","applications":[]},{"id":"VI-15","section":"VI","name":"Sonderbehandlung (special pleading)","page":9,"definition":"Für die eigene Position werden unbegründet Ausnahmen zugelassen.","example":"«Alle müssen Regeln befolgen, ausser mein Lieblingsprojekt.»","applications":[{"argument":"A101","scene":"s35"}]},{"id":"VI-16","section":"VI","name":"Doppelter Standard","page":9,"definition":"Vergleichbare Fälle werden ohne sachlichen Grund unterschiedlich bewertet.","example":"Bei der eigenen Gruppe gilt ein Fehler als Ausnahme, bei der anderen als Beweis.","applications":[{"argument":"A152","scene":"s51"}]},{"id":"VI-17","section":"VI","name":"Unbegründete Beweislastumkehr","page":9,"definition":"Die Gegenseite soll eine unbelegte Behauptung widerlegen.","example":"«Beweise, dass meine geheime Verschwörung nicht existiert.»","applications":[]},{"id":"VI-18","section":"VI","name":"Argument durch Wiederholung (ad nauseam)","page":9,"definition":"Häufige Wiederholung soll fehlende Gründe ersetzen.","example":"«Es ist wahr, weil ich es schon hundertmal gesagt habe.»","applications":[{"argument":"A043","scene":"s16"},{"argument":"A162","scene":"s55"}]},{"id":"VI-19","section":"VI","name":"Argument aus Schweigen","page":9,"definition":"Aus einer fehlenden Erwähnung wird ohne Erwartungsprüfung Nichtexistenz gefolgert.","example":"«Das Protokoll erwähnt keinen Streit; also gab es sicher keinen.»","applications":[]},{"id":"VI-20","section":"VI","name":"Argument aus persönlichem Unglauben","page":9,"definition":"Etwas gilt als falsch, weil man es sich nicht vorstellen kann.","example":"«So ein grosses Projekt kann nicht funktionieren; unvorstellbar.»","applications":[{"argument":"A013","scene":"s05"}]},{"id":"VII-01","section":"VII","name":"Voreilige Verallgemeinerung","page":9,"definition":"Aus zu wenigen Fällen wird eine allgemeine These gemacht.","example":"«Zwei Züge waren zu spät; alle Züge sind unpünktlich.»","applications":[{"argument":"A004","scene":"s02"},{"argument":"A027","scene":"s10"},{"argument":"A047","scene":"s17"},{"argument":"A073","scene":"s26"},{"argument":"A094","scene":"s33"},{"argument":"A121","scene":"s41"},{"argument":"A125","scene":"s43"},{"argument":"A126","scene":"s43"},{"argument":"A146","scene":"s49"}]},{"id":"VII-02","section":"VII","name":"Anekdotischer Beweis","page":9,"definition":"Einzelgeschichte verdrängt systematische Daten.","example":"«Mein Nachbar wurde ohne Training fit; Sport ist unnötig.»","applications":[{"argument":"A023","scene":"s08"},{"argument":"A026","scene":"s10"},{"argument":"A119","scene":"s41"},{"argument":"A123","scene":"s42"},{"argument":"A151","scene":"s51"},{"argument":"A154","scene":"s52"}]},{"id":"VII-03","section":"VII","name":"Selektive Evidenz (Cherry-Picking)","page":9,"definition":"Passende Daten werden gezeigt, widersprechende verschwiegen.","example":"Nur Jahre mit sinkenden Temperaturen werden ausgewählt.","applications":[{"argument":"A136","scene":"s46"}]},{"id":"VII-04","section":"VII","name":"Bestätigungsfehler (confirmation bias)","page":10,"definition":"Belege für eine Vorannahme werden bevorzugt gesucht oder bewertet; primär kognitive Verzerrung.","example":"Man liest nur Studien, die die eigene Meinung stützen.","applications":[{"argument":"A140","scene":"s47"}]},{"id":"VII-05","section":"VII","name":"Survivorship Bias","page":10,"definition":"Nur erfolgreiche oder sichtbare Fälle werden betrachtet.","example":"Von erfolgreichen Start-ups auf die Erfolgschance aller Start-ups schliessen.","applications":[{"argument":"A137","scene":"s46"}]},{"id":"VII-06","section":"VII","name":"Auswahlverzerrung (selection bias)","page":10,"definition":"Die Auswahl der Beobachtungen verzerrt die Schlussfolgerung.","example":"Eine Onlineumfrage zur Internetnutzung nur unter Influencern.","applications":[]},{"id":"VII-07","section":"VII","name":"Nicht repräsentative Stichprobe","page":10,"definition":"Stichprobenmerkmale stimmen nicht mit der Zielpopulation überein.","example":"Aus einer Schulklasse auf alle Jugendlichen der Schweiz schliessen.","applications":[{"argument":"A156","scene":"s53"}]},{"id":"VII-08","section":"VII","name":"Basishäufigkeitsfehler (base-rate neglect)","page":10,"definition":"Vorwahrscheinlichkeit wird bei einem neuen Hinweis ignoriert.","example":"Bei seltener Krankheit wird ein positiver Test als nahezu sicherer Beweis angesehen.","applications":[]},{"id":"VII-09","section":"VII","name":"Konjunktionsfehlschluss","page":10,"definition":"«A und B» wird für wahrscheinlicher als «A» gehalten.","example":"«Sie ist Bankangestellte und Aktivistin» kann nicht wahrscheinlicher als «Bankangestellte» sein.","applications":[]},{"id":"VII-10","section":"VII","name":"Prosecutor's fallacy","page":10,"definition":"P(Evidenz gegeben unschuldig) wird mit P(unschuldig gegeben Evidenz) verwechselt.","example":"«Nur 1 von 1000 Unschuldigen passt zum DNA-Profil; also 99,9 % schuldig.»","applications":[]},{"id":"VII-11","section":"VII","name":"Ökologischer Fehlschluss","page":10,"definition":"Aus Gruppenstatistiken wird auf einzelne Mitglieder geschlossen.","example":"Ein reicher Bezirk bedeutet nicht, dass jede dort lebende Person reich ist.","applications":[{"argument":"A161","scene":"s54"}]},{"id":"VII-12","section":"VII","name":"Atomistischer Fehlschluss","page":10,"definition":"Von Individualzusammenhängen wird unzulässig auf Gruppenebene geschlossen.","example":"Was innerhalb einer Klasse gilt, muss nicht für Klassenmittelwerte gelten.","applications":[{"argument":"A080","scene":"s28"}]},{"id":"VII-13","section":"VII","name":"Simpson-Paradoxon übersehen","page":10,"definition":"Ein Trend in Teilgruppen kehrt sich aggregiert durch unterschiedliche Gruppengewichte um.","example":"Ein Verfahren ist in beiden Risikogruppen erfolgreicher, aber insgesamt weniger erfolgreich.","applications":[]},{"id":"VII-14","section":"VII","name":"Regression zur Mitte missdeutet","page":10,"definition":"Extreme Werte nähern sich häufig von selbst dem Durchschnitt; Effekt wird einer Massnahme zugeschrieben.","example":"Nach einem besonders schlechten Test folgt ein besserer; die Strafpredigt soll Ursache gewesen sein.","applications":[]},{"id":"VII-15","section":"VII","name":"Texas-Sharpshooter / nachträgliches Muster","page":10,"definition":"Nach Sichtung der Daten wird ein zufälliges Muster als geplante Vorhersage ausgegeben.","example":"Aus tausend Zufallszahlen wird erst im Nachhinein ein «Treffer» markiert.","applications":[]},{"id":"VII-16","section":"VII","name":"Überanpassung (overfitting)","page":10,"definition":"Ein Modell lernt zufälliges Rauschen statt verallgemeinerbarer Struktur.","example":"Ein Modell trifft Trainingsdaten perfekt, versagt an neuen Fällen.","applications":[]},{"id":"VII-17","section":"VII","name":"P-Hacking / multiple Tests","page":10,"definition":"Viele Analysen werden durchgeführt; nur statistisch «signifikante» Ergebnisse werden präsentiert.","example":"20 Merkmale testen und bloss den Zufallstreffer veröffentlichen.","applications":[]},{"id":"VII-18","section":"VII","name":"Verwechslung von Risikoarten","page":11,"definition":"Absolute und relative Risikoreduktion werden vermischt.","example":"«50 % weniger Risiko» klingt enorm, kann 2 auf 1 von 1000 bedeuten.","applications":[]},{"id":"VII-19","section":"VII","name":"Fehlschluss des Spielers (gambler's fallacy)","page":11,"definition":"Bei unabhängigen Ereignissen wird ein Ausgleich erwartet.","example":"Nach fünfmal Kopf muss angeblich Zahl kommen.","applications":[]},{"id":"VII-20","section":"VII","name":"Hot-Hand-Fehlschluss","page":11,"definition":"Eine kurze Erfolgsserie wird ohne Evidenz als dauerhafte erhöhte Trefferchance interpretiert.","example":"Drei Treffer nacheinander beweisen nicht, dass der nächste Wurf sicher trifft.","applications":[]},{"id":"VII-21","section":"VII","name":"Fehler der kleinen Zahlen","page":11,"definition":"Kleine Stichproben werden für ähnlich stabil wie grosse gehalten.","example":"Vier Würfe ohne «Sechs» sollen einen gezinkten Würfel beweisen.","applications":[]},{"id":"VII-22","section":"VII","name":"Scheingenauigkeit","page":11,"definition":"Ungewissheit und Messfehler werden durch überpräzise Zahlen verborgen.","example":"«Die Wirkung beträgt exakt 12,738 Prozent» bei ungenauer Datengrundlage.","applications":[{"argument":"A061","scene":"s22"},{"argument":"A087","scene":"s31"},{"argument":"A089","scene":"s31"},{"argument":"A090","scene":"s31"}]},{"id":"VII-23","section":"VII","name":"Falsche Äquivalenz","page":11,"definition":"Sachlich ungleiche Dinge werden als gleichwertig dargestellt.","example":"Ein kleiner Buchungsfehler wird mit systematischem Betrug gleichgesetzt.","applications":[]},{"id":"VII-24","section":"VII","name":"Falsche Ausgewogenheit","page":11,"definition":"Ungleich gut belegte Positionen erhalten denselben epistemischen Rang.","example":"Ein wissenschaftlicher Konsens und eine unbelegte Behauptung gelten als gleich starke Belege.","applications":[]},{"id":"VIII-01","section":"VIII","name":"Post hoc ergo propter hoc","page":11,"definition":"Weil B nach A geschieht, soll A die Ursache sein.","example":"Nach einer neuen App steigen Noten; die App muss der Grund sein.","applications":[{"argument":"A107","scene":"s37"}]},{"id":"VIII-02","section":"VIII","name":"Cum hoc ergo propter hoc","page":11,"definition":"Gleichzeitiges Auftreten wird als Ursache gedeutet.","example":"Mehr Glaceverkauf und mehr Badeunfälle im Sommer: Glace verursacht nicht automatisch Unfälle.","applications":[]},{"id":"VIII-03","section":"VIII","name":"Korrelation ist Kausalität","page":11,"definition":"Aus einem statistischen Zusammenhang folgt ohne Zusatzbelege eine Ursachenbehauptung.","example":"Mehr Bibliotheken korrelieren mit grösseren Städten; Bibliotheken verursachen nicht deren Grösse.","applications":[]},{"id":"VIII-04","section":"VIII","name":"Umgekehrte Kausalität","page":11,"definition":"Die Wirkrichtung wird vertauscht.","example":"«Wer viel übt, ist oft gut; daher üben nur die Guten» (statt umgekehrt oder beides).","applications":[]},{"id":"VIII-05","section":"VIII","name":"Ignorierte Drittvariable","page":11,"definition":"Eine gemeinsame Ursache für A und B wird übersehen.","example":"Hitze erhöht sowohl Glaceverkäufe als auch Schwimmbadbesuche.","applications":[{"argument":"A002","scene":"s01"},{"argument":"A059","scene":"s22"},{"argument":"A155","scene":"s52"}]},{"id":"VIII-06","section":"VIII","name":"Monokausaler Fehlschluss","page":11,"definition":"Ein komplexes Ereignis wird einer einzigen Ursache zugeschrieben.","example":"«Die Schulnote hängt ausschliesslich vom IQ ab.»","applications":[{"argument":"A003","scene":"s02"},{"argument":"A012","scene":"s04"},{"argument":"A017","scene":"s06"},{"argument":"A019","scene":"s07"},{"argument":"A033","scene":"s12"},{"argument":"A048","scene":"s17"},{"argument":"A049","scene":"s18"},{"argument":"A060","scene":"s22"},{"argument":"A073","scene":"s26"},{"argument":"A104","scene":"s36"},{"argument":"A117","scene":"s40"},{"argument":"A139","scene":"s47"},{"argument":"A147","scene":"s49"}]},{"id":"VIII-07","section":"VIII","name":"Falsche Analogie","page":12,"definition":"Übertragene Gemeinsamkeiten sind für die Schlussfolgerung irrelevant.","example":"«Eine Schule ist wie eine Fabrik, also sollen Lernende wie Werkstücke behandelt werden.»","applications":[{"argument":"A010","scene":"s04"},{"argument":"A011","scene":"s04"},{"argument":"A024","scene":"s09"},{"argument":"A050","scene":"s18"},{"argument":"A079","scene":"s28"},{"argument":"A081","scene":"s28"},{"argument":"A093","scene":"s32"},{"argument":"A095","scene":"s33"},{"argument":"A109","scene":"s37"},{"argument":"A132","scene":"s45"}]},{"id":"VIII-08","section":"VIII","name":"Schiefe Ebene (slippery slope)","page":12,"definition":"Eine Kette drastischer Folgen wird ohne ausreichende Verbindung behauptet.","example":"«Eine spätere Abgabefrist führt zwangsläufig zum Ende aller Regeln.»","applications":[{"argument":"A130","scene":"s44"}]},{"id":"VIII-09","section":"VIII","name":"Dominoeffekt ohne Mechanismus","page":12,"definition":"Ein Ereignis soll zwangsläufig andere auslösen; Zwischenschritte fehlen.","example":"«Eine einzelne Ausnahme zerstört das gesamte Schulsystem.»","applications":[{"argument":"A028","scene":"s10"},{"argument":"A076","scene":"s27"}]},{"id":"VIII-10","section":"VIII","name":"Nirwanafehlschluss (nirvana fallacy)","page":12,"definition":"Reale Lösungen werden mit einem unrealistisch perfekten Ideal verglichen.","example":"«Die Reform löst nicht alle Probleme; also sollte man sie verwerfen.»","applications":[{"argument":"A074","scene":"s26"}]},{"id":"VIII-11","section":"VIII","name":"Perfektionistischer Fehlschluss","page":12,"definition":"Eine Massnahme wird wegen unvollständiger Wirkung als wertlos abgelehnt.","example":"«Velowege beseitigen nicht alle Unfälle; daher sind sie sinnlos.»","applications":[]},{"id":"VIII-12","section":"VIII","name":"Falscher Mittelweg (middle-ground fallacy)","page":12,"definition":"Die Wahrheit soll automatisch zwischen zwei Behauptungen liegen.","example":"Eine Person sagt 2+2=4, die andere 2+2=6; «Kompromiss» 5.","applications":[]},{"id":"VIII-13","section":"VIII","name":"Fehlerhafte Extrapolation","page":12,"definition":"Ein beobachteter Trend wird ohne Beachtung veränderter Bedingungen fortgeschrieben.","example":"«Die Besucherzahl verdoppelte sich einmal; also verdoppelt sie sich jedes Jahr.»","applications":[{"argument":"A015","scene":"s05"},{"argument":"A016","scene":"s06"}]},{"id":"VIII-14","section":"VIII","name":"Unbegründete Gewissheit über Zukunft","page":12,"definition":"Eine Prognose wird ohne Angaben zu Annahmen oder Unsicherheit als zwingend dargestellt.","example":"«Weil eine Umfrage führt, ist die Wahl entschieden.»","applications":[{"argument":"A014","scene":"s05"},{"argument":"A021","scene":"s07"},{"argument":"A031","scene":"s11"},{"argument":"A044","scene":"s16"},{"argument":"A056","scene":"s21"},{"argument":"A062","scene":"s22"},{"argument":"A077","scene":"s27"},{"argument":"A082","scene":"s29"},{"argument":"A092","scene":"s32"},{"argument":"A096","scene":"s33"},{"argument":"A106","scene":"s37"}]},{"id":"VIII-15","section":"VIII","name":"Planungsfehlschluss","page":12,"definition":"Zeitbedarf wird aufgrund optimistischer Erwartungen systematisch unterschätzt.","example":"«Die Projektarbeit ist sicher in einer Stunde fertig», trotz gegenteiliger Erfahrung.","applications":[]},{"id":"VIII-16","section":"VIII","name":"Fehlschluss versunkener Kosten (sunk cost)","page":12,"definition":"Bereits unwiederbringliche Kosten bestimmen eine neue Entscheidung.","example":"«Wir haben so viel investiert; daher müssen wir weitermachen, obwohl der Nutzen negativ ist.»","applications":[]},{"id":"IX-01","section":"IX","name":"Sein-Sollen-Fehlschluss (is–ought gap)","page":12,"definition":"Aus blossen Tatsachen wird ohne normative Prämisse eine Pflicht gefolgert.","example":"«Menschen streiten oft; also sollen sie streiten.»","applications":[{"argument":"A005","scene":"s02"},{"argument":"A007","scene":"s03"},{"argument":"A036","scene":"s14"},{"argument":"A037","scene":"s14"},{"argument":"A052","scene":"s19"},{"argument":"A063","scene":"s23"},{"argument":"A064","scene":"s23"},{"argument":"A069","scene":"s24"},{"argument":"A071","scene":"s25"},{"argument":"A100","scene":"s34"},{"argument":"A124","scene":"s42"},{"argument":"A129","scene":"s44"},{"argument":"A142","scene":"s48"},{"argument":"A158","scene":"s53"}]},{"id":"IX-02","section":"IX","name":"Naturalistischer Fehlschluss (umstrittener Begriff)","page":12,"definition":"Wert wird mit einer natürlichen Eigenschaft identifiziert; nicht jede Berufung auf Natur ist identisch damit.","example":"«Gut» sei definitionsgemäss nichts anderes als «was Lust erzeugt».","applications":[{"argument":"A144","scene":"s48"}]},{"id":"IX-03","section":"IX","name":"Moralistischer Fehlschluss","page":12,"definition":"Aus einem erwünschten Soll wird auf die faktische Wirklichkeit geschlossen.","example":"«Alle sollten gleich gute Chancen haben; also gibt es keine Unterschiede.»","applications":[]},{"id":"IX-04","section":"IX","name":"Relativer Privationsfehlschluss","page":13,"definition":"Ein Problem wird wegen eines grösseren Problems für irrelevant erklärt.","example":"«Andere leiden stärker; darum sind Mobbingfälle unwichtig.»","applications":[{"argument":"A053","scene":"s20"}]},{"id":"IX-05","section":"IX","name":"Zweifaches Unrecht («two wrongs make a right»)","page":13,"definition":"Falsches Verhalten anderer dient als Rechtfertigung eigenen Fehlverhaltens.","example":"«Sie haben betrogen; daher darf ich auch betrügen.»","applications":[{"argument":"A110","scene":"s38"},{"argument":"A152","scene":"s51"}]},{"id":"IX-06","section":"IX","name":"Fehlschluss der fairen Welt","page":13,"definition":"Erfolge und Leiden werden ohne Evidenz als verdient gedeutet.","example":"«Wer arm ist, hat wohl einfach zu wenig gearbeitet.»","applications":[]},{"id":"IX-07","section":"IX","name":"Fehler der Mehrheitsmoral","page":13,"definition":"Eine verbreitete Norm wird ohne eigenständige Begründung für richtig gehalten.","example":"«Die meisten finden es akzeptabel; also ist es moralisch richtig.»","applications":[{"argument":"A133","scene":"s45"}]},{"id":"IX-08","section":"IX","name":"Falscher Vergleich von Pflichten","page":13,"definition":"Aus einer Pflicht in Situation A wird ohne Kontext eine identische Pflicht in B gefolgert.","example":"«Bei jedem Risiko müssen stets dieselben Massnahmen gelten.»","applications":[{"argument":"A065","scene":"s23"},{"argument":"A068","scene":"s24"},{"argument":"A088","scene":"s31"},{"argument":"A091","scene":"s32"},{"argument":"A115","scene":"s39"}]},{"id":"X-01","section":"X","name":"Gish-Gallop","page":13,"definition":"Sehr viele schwache Behauptungen werden schneller vorgetragen, als sie einzeln überprüft werden können.","example":"Zwanzig unbelegte Vorwürfe in einer Minute statt eines überprüfbaren Arguments.","applications":[]},{"id":"X-02","section":"X","name":"Sealioning","page":13,"definition":"Hartnäckige, scheinbar höfliche Nachfragen können zur Erschöpfung eingesetzt werden; Kontext entscheidet.","example":"Nach vielen Quellen werden immer neue Nachweise gefordert, ohne auf Antworten einzugehen.","applications":[]},{"id":"X-03","section":"X","name":"Zitieren ausser Kontext (contextomy)","page":13,"definition":"Ein Zitat wird so gekürzt, dass es eine andere Aussage nahelegt.","example":"Aus «Wir haben nicht behauptet, dass alle scheitern» wird verkürzt «alle scheitern».","applications":[]},{"id":"X-04","section":"X","name":"Verschiebung der Streitfrage","page":13,"definition":"Das ursprüngliche Problem wird unbemerkt gegen ein anderes ausgetauscht.","example":"Aus «Ist die Zahl korrekt?» wird «Sind Zahlen überhaupt wichtig?».","applications":[]},{"id":"X-05","section":"X","name":"Motivated reasoning","page":13,"definition":"Wunschdenken beeinflusst die Auswahl und Deutung von Belegen; psychologisches Muster, nicht eigenständige Schlussform.","example":"Die eigene Partei wird bei identischen Fehlern milder beurteilt.","applications":[]},{"id":"X-06","section":"X","name":"Ankereffekt","page":13,"definition":"Ein zufällig genannter erster Wert beeinflusst spätere Urteile.","example":"Nach dem Anker «10 000 Franken» wirkt ein Preis von 5000 günstig.","applications":[]},{"id":"X-07","section":"X","name":"Verfügbarkeitsheuristik","page":13,"definition":"Leicht erinnerbare Beispiele werden als häufiger eingestuft.","example":"Nach einem spektakulären Unfall überschätzt man das Unfallrisiko.","applications":[{"argument":"A030","scene":"s11"}]},{"id":"X-08","section":"X","name":"Dunning-Kruger-Effekt (vorsichtig verwenden)","page":14,"definition":"Geringe Kompetenz kann mit schlechter Selbsteinschätzung einhergehen; kein Beweis, dass jeder Irrende inkompetent ist.","example":"Wer ein Thema gerade kennengelernt hat, hält seine Kenntnis für vollständig.","applications":[]},{"id":"X-09","section":"X","name":"Halo-Effekt","page":14,"definition":"Ein positiv bewertetes Merkmal färbt auf andere Urteile ab.","example":"Eine rhetorisch starke Person gilt automatisch als fachlich zuverlässig.","applications":[]},{"id":"X-10","section":"X","name":"Fundamentaler Attributionsfehler","page":14,"definition":"Verhalten anderer wird vorschnell mit Persönlichkeit statt Situation erklärt.","example":"«Sie kommt zu spät, weil sie faul ist», obwohl der Zug ausgefallen ist.","applications":[{"argument":"A138","scene":"s47"},{"argument":"A141","scene":"s47"},{"argument":"A161","scene":"s54"}]},{"id":"X-11","section":"X","name":"Rückschaufehler (hindsight bias)","page":14,"definition":"Nach einem Ereignis scheint der Ausgang vorher klar gewesen zu sein.","example":"«Dass das Start-up scheitert, war doch von Anfang an offensichtlich.»","applications":[]},{"id":"X-12","section":"X","name":"Selbstüberschätzung (overconfidence)","page":14,"definition":"Die Sicherheit einer Überzeugung übersteigt die Evidenz.","example":"«Ich liege zu 100 % richtig», obwohl die Datenlage dünn ist.","applications":[]}],"applicationPolicy":"Eine verlinkte Anwendung kann eine Schlussform, eine Abgrenzung, ein nur bedingtes Risiko oder ein zurückgewiesenes Muster sein. Eine Verwendungszahl ist keine Zahl nachgewiesener Fehlschlüsse. Nicht angewandte Kategorien werden nicht künstlich zugeordnet.","statusLabels":{"risiko":"Bedingtes Risiko – kein bestätigter Fehlschluss","abgrenzung":"Abgrenzung – kein Fehlschluss nachgewiesen","zurueckgewiesen":"Im Argument zurückgewiesenes Fehlermuster","diskutiert":"Diskutiertes Muster – nicht individuell diagnostiziert","rhetorik":"Rhetorischer Effekt – kein alleiniger logischer Nachweis","pruefthese":"Vorgeführte Prüfthese – keine Zuschreibung als eigene Überzeugung"},"summary":{"entries":164,"sections":10,"argumentsReviewed":163,"usedEntries":71,"formalReconstructionCount":6}};
